// forth holds the evaluator state: the data stack and the
// user-defined words.
type forth struct {
	words map[string][]string
	stack []int
}

func newForth() *forth {
	return &forth{
		words: make(map[string][]string),
		stack: []int{},
	}
}

// isNumber reports whether tok is a number: an optional minus sign
// followed by one or more ASCII digits.
func isNumber(tok string) bool {
	s := tok
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// parseNumber converts a numeric token to an int.
func parseNumber(tok string) (int, bool) {
	if !isNumber(tok) {
		return 0, false
	}
	n, err := strconv.Atoi(tok)
	if err != nil {
		return 0, false
	}
	return n, true
}

func (f *forth) push(v int) {
	f.stack = append(f.stack, v)
}

// pop removes and returns the top of the stack.
func (f *forth) pop() (int, error) {
	if len(f.stack) == 0 {
		return 0, errStackUnderflow
	}
	v := f.stack[len(f.stack)-1]
	f.stack = f.stack[:len(f.stack)-1]
	return v, nil
}

// pop2 removes and returns the top two values, with the second
// value from the top returned first.
func (f *forth) pop2() (int, int, error) {
	if len(f.stack) < 2 {
		return 0, 0, errStackUnderflow
	}
	b := f.stack[len(f.stack)-1]
	a := f.stack[len(f.stack)-2]
	f.stack = f.stack[:len(f.stack)-2]
	return a, b, nil
}

// exec runs a list of (already lowercased) tokens.
func (f *forth) exec(tokens []string) error {
	for _, tok := range tokens {
		switch tok {
		case "+":
			a, b, err := f.pop2()
			if err != nil {
				return err
			}
			f.push(a + b)
		case "-":
			a, b, err := f.pop2()
			if err != nil {
				return err
			}
			f.push(a - b)
		case "*":
			a, b, err := f.pop2()
			if err != nil {
				return err
			}
			f.push(a * b)
		case "/":
			a, b, err := f.pop2()
			if err != nil {
				return err
			}
			if b == 0 {
				return errDivideByZero
			}
			f.push(a / b)
		case "dup":
			if len(f.stack) == 0 {
				return errStackUnderflow
			}
			f.push(f.stack[len(f.stack)-1])
		case "drop":
